"""Build Hearthline's complete static demo pages from one content source."""
from pathlib import Path
from html import escape
import json
import os
import shutil

ROOT = Path(__file__).resolve().parent
OUT = ROOT / "dist"
ORIGIN = os.environ.get("SITE_URL", "https://hearthline-roofing.vercel.app").rstrip("/")
ROUTES = ["", "roofing", "our-approach", "planning-guide", "inspection-preview"]
NAV = [("Home", ""), ("Roofing", "roofing"), ("Our approach", "our-approach"), ("Planning guide", "planning-guide"), ("Inspection preview", "inspection-preview")]
PHOTOS = {
    "hero": ("Warm residential roofline after rainfall, with terracotta shingles and copper gutter", 1600, 900),
    "roof-detail": ("Illustrative close view of roof edge, gutter and chimney flashing", 1536, 1024),
    "consultation": ("Illustrative conversation about roofing materials at an outdoor table", 1536, 1024),
    "roofline": ("Illustrative residential roofline and dormer at golden hour", 1536, 1024),
    "materials": ("Illustrative shingle and underlayment samples on a worktable", 1536, 1024),
}
MANIFEST = []


def rel(route, depth):
    return ("../" if depth else "") + (route + "/" if route else "")


def picture(name, depth, eager=False):
    alt, width, height = PHOTOS[name]
    path = rel("", depth) + "assets/" + name + ".webp"
    return (f'<img src="{path}" alt="{escape(alt)}; AI-generated illustration" width="{width}" height="{height}" '
            f'loading="{"eager" if eager else "lazy"}" decoding="async"'
            + (' fetchpriority="high"' if eager else '') + ">")


def button(label, route, depth, cls=""):
    return f'<a class="button {cls}" href="{rel(route, depth)}">{escape(label)} <span aria-hidden="true">↗</span></a>'


def page(route, title, description, content):
    depth = 0 if not route else 1
    canonical = ORIGIN + ("/" + route if route else "") + "/"
    nav = "".join(f'<a href="{rel(path, depth)}"' + (' aria-current="page"' if path == route else '') + f'>{label}</a>' for label, path in NAV)
    css = rel("", depth) + "styles.css"
    js = rel("", depth) + "script.js"
    photo = ORIGIN + "/assets/hero.webp"
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description)}"><meta name="robots" content="noindex,follow"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{photo}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)}"><meta name="twitter:description" content="{escape(description)}"><link rel="stylesheet" href="{css}"><script src="{js}" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="demo-label">FIREWORKS CONCEPT · FICTIONAL ROOFING COMPANY · NO REQUESTS ARE SENT</div><header class="site-header"><div class="container header-row"><a class="logo" href="{rel('', depth)}" aria-label="Hearthline Roofing home"><span class="logo-mark" aria-hidden="true">H</span><span>HEARTHLINE<small>ROOFING · DEMO</small></span></a><button class="menu-toggle" type="button" aria-label="Open menu" aria-controls="main-nav" aria-expanded="false"><span></span><span></span><span></span></button><nav id="main-nav" aria-label="Main navigation">{nav}</nav></div></header><main id="main">{content}</main><footer class="footer"><div class="container footer-grid"><div><p class="footer-logo">HEARTHLINE / ROOFING</p><p>Thoughtful roof planning for the place you call home.</p><p class="fine">Fictional FireWorks demo. All photography is AI-generated and illustrative.</p></div><div><p class="eyebrow">Explore</p>{nav}</div><div><p class="eyebrow">Your next step</p><p>Start with a clear description of the concern. A real contractor would confirm all findings, scope and availability.</p>{button('Try the inspection preview', 'inspection-preview', depth)}</div></div><div class="container footer-bottom">No inspections, requests, or appointments are made through this demo.</div></footer></body></html>'''
    destination = OUT / route
    destination.mkdir(parents=True, exist_ok=True)
    (destination / "index.html").write_text(html)
    MANIFEST.append({"path": "/" + route + "/" if route else "/", "title": title, "description": description, "canonical": canonical})


def intro(kicker, title, copy):
    return f'<section class="inner-intro container"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{copy}</p></section>'


hero = f'''<section class="hero"><div class="hero-image">{picture('hero', 0, True)}<span class="image-note">Illustrative AI-generated scene</span></div><div class="hero-copy container"><div class="hero-panel"><p class="eyebrow">A clearer way to care for your roof</p><h1>Protect what<br><em>happens beneath.</em></h1><p class="lead">A roof decision deserves more than a fast guess. Explore repairs, replacement and the questions that lead to a useful written scope.</p><div class="actions">{button('Start an inspection preview','inspection-preview',0)}{button('Explore roofing options','roofing',0,'outline')}</div><p class="hero-sub">Residential roof planning · Fictional website concept</p></div></div></section>'''
trust = '''<section class="proof-band"><div class="container proof-inner"><p class="eyebrow">Proof a real roofer can show</p><div class="proof-list"><article><b>Documented scope</b><span>Before-and-after details with context and permission</span></article><article><b>Material clarity</b><span>Real product specifications and written exclusions</span></article><article><b>Verified reputation</b><span>Links to actual third-party reviews and credentials</span></article></div><p class="fine">Demo placeholders only. No reviews, completed jobs or credentials are claimed here.</p></div></section>'''
split_one = f'''<section class="section container editorial"><figure>{picture('roof-detail',0)}<figcaption>Illustrative roof detail, not a completed Hearthline project.</figcaption></figure><div class="editorial-copy"><p class="eyebrow">01 / Look closer</p><h2>Start with the condition, not the pitch.</h2><p>Leaks, aging shingles and weather wear call for different conversations. A real inspection should explain what can be seen, what cannot, and which options fit the roof in front of you.</p><ul><li>Document the concern</li><li>Ask about repair versus replacement</li><li>Get the scope in writing</li></ul>{button('See the roofing options','roofing',0)}</div></section>'''
split_two = f'''<section class="section cream"><div class="container editorial reverse"><div class="editorial-copy"><p class="eyebrow">02 / Choose deliberately</p><h2>Materials matter. So does the plan.</h2><p>Compare ventilation, underlayment, flashing, site protection and cleanup along with the visible finish. The best next step is a written proposal you can actually understand.</p>{button('Use the planning guide','planning-guide',0)}</div><figure>{picture('materials',0)}<figcaption>Illustrative material study; not a product specification.</figcaption></figure></div></section>'''
slider = f'''<section class="slider-section" aria-labelledby="slider-title"><div class="container slider-heading"><div><p class="eyebrow">A closer look</p><h2 id="slider-title">The details around the roofline.</h2></div><p>Swipe, use the arrow keys when focused, or choose an image below. These scenes are illustrative.</p></div><div class="slider" data-slider tabindex="0" aria-label="Illustrative roofing scenes"><div class="slider-viewport"><div class="slides"><figure class="slide" id="slide-1">{picture('consultation',0)}<figcaption>Start with a conversation about scope and priorities.</figcaption></figure><figure class="slide" id="slide-2">{picture('roofline',0)}<figcaption>Consider the full roofline, not only a single surface.</figcaption></figure></div></div><div class="slider-controls container"><button type="button" data-prev aria-label="Previous photo">←</button><div class="slider-dots" role="group" aria-label="Choose a photo"><button type="button" data-slide="0" aria-label="Show consultation photo" aria-current="true"></button><button type="button" data-slide="1" aria-label="Show roofline photo" aria-current="false"></button></div><button type="button" data-next aria-label="Next photo">→</button></div></div></section>'''
final = f'''<section class="closing"><div class="container closing-inner"><p class="eyebrow">Plan the next conversation</p><h2>Know what you need to ask before you choose.</h2><p>Try the local inspection preview and see how a clear request could be framed.</p>{button('Start an inspection preview','inspection-preview',0)}</div></section>'''
page("", "Hearthline Roofing | Residential Roofing Website Demo", "Explore Hearthline Roofing, a fictional residential roofing website with repair and replacement planning and a local-only inspection preview.", hero + trust + split_one + split_two + slider + final)

services = '''<section class="section container detail-list"><article><span>01</span><div><h2>Roof assessment</h2><p>Discuss visible wear, leak history, age and access. A qualified professional confirms the condition and explains inspection limits.</p></div></article><article><span>02</span><div><h2>Targeted repair</h2><p>Ask whether a localized repair is appropriate, what materials are used, and what remains outside the quoted work.</p></div></article><article><span>03</span><div><h2>Full replacement</h2><p>Compare material, flashing, ventilation, underlayment, disposal, timeline and site protection in a written proposal.</p></div></article></section>'''
page("roofing", "Roofing Options | Hearthline Roofing Demo", "Compare roof assessments, repair and replacement planning in the fictional Hearthline Roofing website demo.", intro("Roofing options", "A roof decision with <em>room to think.</em>", "The right option depends on an actual inspection. These are the conversations a homeowner can begin before choosing a contractor.") + services + final.replace('inspection-preview/','../inspection-preview/'))

approach = f'''<section class="section container editorial"><figure>{picture('consultation',1)}<figcaption>AI-generated illustrative consultation, not actual staff or customers.</figcaption></figure><div class="editorial-copy"><p class="eyebrow">A transparent process</p><h2>Good work starts with better questions.</h2><p>Hearthline is a fictional brand built to show how a roofing company can communicate clearly: listen to the concern, explain the inspection, and document the proposed work.</p><p>Real client sites should replace these scenes and proof prompts with licensed material, approved customer stories and verified credentials.</p>{button('Explore the planning guide','planning-guide',1)}</div></section>'''
page("our-approach", "Our Approach | Hearthline Roofing Demo", "Learn the transparent, homeowner-focused process illustrated by the fictional Hearthline Roofing concept.", intro("Our approach", "Clarity is a form of <em>craft.</em>", "A useful roofing conversation should leave you with fewer unanswered questions.") + approach + trust + f'<section class="container section">{button("Start an inspection preview","inspection-preview",1)}</section>')

guide = '''<section class="section container"><div class="guide-grid"><article><span>01</span><h2>Gather the history</h2><p>Note roof age, past repairs, visible interior marks and the timing of any leak.</p></article><article><span>02</span><h2>Ask about the whole system</h2><p>Discuss flashing, drainage, ventilation and underlayment rather than only the shingle color.</p></article><article><span>03</span><h2>Compare written scope</h2><p>Check materials, exclusions, site protection, schedule, cleanup and warranty terms.</p></article></div><div class="faq"><h2>Questions to bring</h2><details><summary>Can photos tell me whether I need a new roof?</summary><p>Photos can show visible concerns but cannot replace an on-site assessment by a qualified contractor.</p></details><details><summary>Does this demo book an inspection?</summary><p>No. The form is a local preview only. It does not send information, reserve a time or contact anyone.</p></details><details><summary>Are the projects and reviews real?</summary><p>No. Hearthline is a fictional demo, and its photographs and proof prompts are illustrative.</p></details></div></section>'''
page("planning-guide", "Roof Planning Guide | Hearthline Roofing Demo", "Three practical steps for discussing roof condition, materials and written scope in the Hearthline Roofing demo.", intro("Planning guide", "Know the questions before <em>the quote.</em>", "A little preparation makes the scope easier to understand and compare.") + guide + f'<section class="container section">{button("Try the inspection preview","inspection-preview",1)}</section>')

form = '''<section class="section container request-grid"><aside><p class="eyebrow">Local-only preview</p><h2>Frame a useful first conversation.</h2><p>This demonstration is not connected to a roofer. Use sample details to see a summary, then close the page to clear them.</p><div class="disclosure">No photos, personal information, requests or appointments leave your browser.</div></aside><div><form id="request-form"><label>Your name<input name="name" autocomplete="name" required minlength="2"></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>What are you planning?<select name="project" required><option value="">Choose an option</option><option>Inspection conversation</option><option>Targeted repair</option><option>Replacement planning</option></select></label><label>What have you noticed?<textarea name="concern" required minlength="10" maxlength="500" rows="4" placeholder="For example, a ceiling mark after heavy rain"></textarea></label><label>Preferred conversation window<select name="window" required><option value="">Choose an option</option><option>Morning</option><option>Afternoon</option><option>Flexible</option></select></label><label class="consent"><input type="checkbox" name="consent" required> I understand this is a local demo and no request is sent.</label><button class="button" type="submit">Preview my request <span aria-hidden="true">↗</span></button><p class="fine">Please use sample contact details. This form never transmits or stores them.</p></form><section id="request-summary" class="summary" hidden aria-live="polite"><h2>Your sample request</h2><p>Nothing was sent or booked. This is how your information could be organized for a real contractor:</p><dl id="summary-values"></dl><button type="button" id="edit-request" class="button outline">Edit preview</button></section><noscript><p>The preview form requires JavaScript. All other page content is available without it.</p></noscript></div></section>'''
page("inspection-preview", "Inspection Request Preview | Hearthline Roofing Demo", "Try a local-only residential roofing inquiry preview. No inspection is requested or booked.", intro("Inspection preview", "Begin with what <em>you know.</em>", "A focused description can make the next conversation more useful.") + form)

# A real standalone 404, not a reused public page shell.
(OUT / "404.html").write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page Not Found | Hearthline Roofing Demo</title><meta name="description" content="The requested Hearthline Roofing demo page could not be found."><meta name="robots" content="noindex,follow"><link rel="canonical" href="{ORIGIN}/404"><meta property="og:title" content="Page Not Found | Hearthline Roofing Demo"><meta property="og:description" content="The requested Hearthline Roofing demo page could not be found."><meta property="og:url" content="{ORIGIN}/404"><link rel="stylesheet" href="styles.css"></head><body><div class="demo-label">FIREWORKS CONCEPT · FICTIONAL ROOFING COMPANY</div><main class="inner-intro container"><p class="eyebrow">404 / Page not found</p><h1>This page isn’t here.</h1><p class="lead">Return home to explore the Hearthline demo.</p><a class="button" href="./">Back to the home page <span aria-hidden="true">↗</span></a></main></body></html>''')
(OUT / "sitemap.xml").write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + ''.join(f'<url><loc>{row["canonical"]}</loc></url>' for row in MANIFEST) + '</urlset>')
(OUT / "robots.txt").write_text("User-agent: *\nAllow: /\n# Demo pages carry noindex.\nSitemap: " + ORIGIN + "/sitemap.xml\n")
(OUT / "rendering-manifest.json").write_text(json.dumps(MANIFEST, indent=2))
for name in ["styles.css", "script.js", "vercel.json"]:
    shutil.copy2(ROOT / name, OUT / name)
shutil.copytree(ROOT / "assets", OUT / "assets", dirs_exist_ok=True)
print(f"Built {len(MANIFEST)} complete HTML routes into {OUT}")
